def solve2(G, top_target=1):
    H,W=len(G),len(G[0])
    s={}
    for i,r in enumerate(G):
        for j,v in enumerate(r):
            if v: s.setdefault(v,[]).append((i,j))
    out=[[0]*W for _ in range(H)]
    for c,cells in s.items():
        t=min(i for i,_ in cells)
        cols=[j for _,j in cells]; c0,c1=min(cols),max(cols); ctr=(c0+c1)/2
        for i,j in cells:
            if i==t:  # center top-row group about bbox center
                js=[k for ii,k in cells if ii==t]
                lo,hi=min(js),max(js)
                j=j+int(round(ctr-(lo+hi)/2))
            out[i-(t-top_target)][j]=c
    return out
